module Prob_8_10 (input x, y, clock, reset_b);  reg [ 1: 0] 	state, next_state;  parameter	s0 = 2'b00, s1 = 2'b01, s2 = 2'b10, s3 = 2'b11;  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) state <= s0; else state <= next_state;  always @ (state, x, y) begin    next_state = s0;    case (state)      s0:	if (x == 0) next_state = s0; else next_state = s1;      s1:	if (y == 0) next_state = s2; else next_state = s3;      s2:	if (x == 0) next_state = s0; else if (y == 0) next_state = s2; else next_state = s3;      s3:	if (x == 0) next_state = s0; else if (y == 0) next_state = s2; else next_state = s3;    endcase  endendmodulemodule t_Prob_8_10 ();  reg x, y, clock, reset_b;  Prob_8_10 M0 (x, y, clock, reset_b);  initial #150 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    reset_b = 0;     #12 reset_b = 1;      x = 0; y = 0;		// Remain in s0    #10 y = 1;			// Remain in s0    #20 x = 1;			// Go to s1 to s3    #40 reset_b = 0;	// Go to s0    #42 reset_b = 1;	// Go to s2 to s3     #60 y = 0;			// Go to s2    #80 y = 1;			// Go to s3    #90	x = 0;			// Go to s0    #100 x = 1;			// Go to s1    #110 y = 0;			// Go to s2    #130	x = 0;		// Go to s0  joinendmodule